import{_ as a,o as l,c as r,a2 as i}from"./chunks/framework.F7eQ-ohH.js";const e="/bzygq/assets/quesion_imgs_ecf6a3bc14ad421ebeb5984309fe1336.CdB0wHSb.png",o="/bzygq/assets/quesion_imgs_0b72a905e6624d5eb54d78b882d313f6.gd4-1kBv.png",d="/bzygq/assets/quesion_imgs_7121fc4ffc3d437fb711a99ff123bed6.C-ky5kbL.png",n="/bzygq/assets/quesion_imgs_4bb702da47b14bdd8f7f597ee31fd686.Bs8Hypk5.png",s="/bzygq/assets/quesion_imgs_8f9dfa642563473886986580dfda5dc3.ChnIA09Y.png",h="/bzygq/assets/quesion_imgs_1d041c1f54c74d409271dde00b019e8c.R4o8vBO4.png",b="/bzygq/assets/quesion_imgs_03cfa302fc984cc4b54c41f49f9778e6.Dr0NRQwO.png",C="/bzygq/assets/quesion_imgs_9e2b3523e30f4052b156e503d71660cc.orjl9QGx.png",c="/bzygq/assets/quesion_imgs_912f912cfc4e446fbbad490f5b0c5302.CMvnF7vQ.png",g="/bzygq/assets/quesion_imgs_8044f5aecbfe411ebc657724fbb3fe4d.C2ijkDXL.png",p="/bzygq/assets/quesion_imgs_8f0f7b06c228415ca8d8ccdc5d4e37f7.Lq12GXel.png",u="/bzygq/assets/quesion_imgs_174c9b6741544699964fc624ce8b50c9.KWl_cVPY.png",P="/bzygq/assets/quesion_imgs_7770fb0c55544ae5b9697ee3e76ea5e3.BVAWWMsT.png",A="/bzygq/assets/quesion_imgs_e8bee06650dd4b14ad259cc68a7886c2.BbqSdrs2.png",q="/bzygq/assets/quesion_imgs_174c9b6741544699964fc624ce8b50c9.KWl_cVPY.png",m="/bzygq/assets/quesion_imgs_c4b59b6273f6448682a05095cb5283df.DCQZz3cp.png",B=JSON.parse('{"title":"Part 05：数据链路层","description":"","frontmatter":{},"headers":[],"relativePath":"科技岗专业课/计算机网络/5、数据链路层.md","filePath":"科技岗专业课/计算机网络/5、数据链路层.md","lastUpdated":1788883925000}'),f={name:"科技岗专业课/计算机网络/5、数据链路层.md"};function x(M,t,S,_,k,D){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="part-05-数据链路层" tabindex="-1"><strong>Part 05：数据链路层</strong> <a class="header-anchor" href="#part-05-数据链路层" aria-label="Permalink to &quot;**Part 05：数据链路层**&quot;">​</a></h1><table tabindex="0"><thead><tr><th>【原创声明】大家好，我是say，是这篇文章的原创作者！985硕士毕业，应届进入某大厂后道心破碎，社招上岸多家855半垄断央企，因为自己淋过雨，希望帮大家撑把伞，帮助更多同学找到不内卷、能够好好生活的央国企，已帮助1000+同学上岸央国企，需要连联系学长的加微信：wx_hxsay</th></tr></thead></table><h2 id="数据链路层" tabindex="-1">数据链路层 <a class="header-anchor" href="#数据链路层" aria-label="Permalink to &quot;数据链路层&quot;">​</a></h2><p>数据链路层是计算机网络体系结构中的重要层次，主要负责将物理层接收到的原始比特流转换为有意义的帧，并在相邻节点之间进行可靠的数据传输。</p><h2 id="什么是数据链路层" tabindex="-1">什么是数据链路层？ <a class="header-anchor" href="#什么是数据链路层" aria-label="Permalink to &quot;什么是数据链路层？&quot;">​</a></h2><p>数据链路层一般负责将物理层接收到的原始比特流转换为有意义的帧，并在相邻节点之间进行可靠的数据传输。通过各种协议和机制，确保数据在物理链路上的正确传输，为网络层提供无差错的服务</p><p>其中链路是指从一个节点到相邻节点的一段物理线路，中间没有任何其它交换节点。在一条线路上传输数据时，除了物理线路外，还需要通信协议来控制数据传输。将实现这些协议的硬件和软件添加到链路上，就构成了数据链路层 。</p><h2 id="数据链路层功能" tabindex="-1">数据链路层功能 <a class="header-anchor" href="#数据链路层功能" aria-label="Permalink to &quot;数据链路层功能&quot;">​</a></h2><ol><li>**帧的封装与解封：**将网络层传来的数据封装成帧，添加帧头和帧尾等控制信息，以便在物理链路上传输。在接收端，将接收到的帧进行解封，去除控制信息，将数据交给网络层。</li><li>**物理地址寻址：**在局域网中，数据链路层使用物理地址（MAC地址）来标识网络中的设备。通过MAC地址，数据链路层可以将帧准确地发送到目标设备，实现点到点或广播式的数据传输。</li><li>**流量控制：**当发送方的发送速度超过接收方的接收速度时，会导致数据丢失。数据链路层通过流量控制机制，如停止等待协议、滑动窗口协议等，使发送方的发送速度与接收方的接收速度相匹配，避免数据丢失。</li><li>**差错控制：**由于物理链路可能存在噪声、干扰等因素，导致数据传输过程中出现错误。数据链路层通过差错检测和纠正机制，如循环冗余校验（CRC）、海明码等，检测和纠正传输过程中出现的错误，确保数据的准确性。</li><li>**链路管理：**负责建立、维护和释放数据链路连接。在通信开始前，数据链路层需要进行链路的初始化和协商，确定通信的参数和方式。在通信过程中，要监测链路的状态，及时处理链路故障等问题。通信结束后，要释放链路资源。</li></ol><h2 id="数据链路层有哪些协议" tabindex="-1">数据链路层有哪些协议？ <a class="header-anchor" href="#数据链路层有哪些协议" aria-label="Permalink to &quot;数据链路层有哪些协议？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>协议名称</th><th>相关说明</th></tr></thead><tbody><tr><td>HDLC（高级数据链路控制）</td><td>典型的数据链路层协议，用于实现链路建立、数据传输和链路释放等功能，能保证传送到下一层的数据在传输过程中准确接收，还能实现流量控制，是面向比特型的同步协议</td></tr><tr><td>PPP（点对点协议）</td><td>为在同等单元之间传输数据包的简单链路设计的链路层协议，主要用于在串行链路（如电话线、串口等）上建立、配置和测试数据链路连接，为网络层协议提供承载服务，支持多种网络层协议、提供链路控制和网络控制功能、支持身份验证等，是目前广域网中使用最广泛的链路层协议之一。由将IP数据报封装到串行链路的方法、链路控制协议LCP、网络控制协议NCP三个部分组成，帧格式包括开始标志字段、地址字段、控制字段、协议字段、数据字段、FCS码字段等，异步传输时使用特殊的字符填充法实现透明传输，同步传输时采用零比特填充方法实现透明传输</td></tr><tr><td>以太网MAC协议</td><td>以太网使用的协议，以太网MAC子层的协议数据单元是帧，负责将上层传来的数据封装成帧，并通过物理层发送到网络中，同时处理帧的接收和错误检测等功能</td></tr><tr><td>CSMA/CD（载波侦听多路访问/碰撞检测协议）</td><td>适用于总线型网络或者半双工网络环境，以太网使用该协议，提供不可靠的交付（即尽最大努力的交付），多点接入说明是总线型网络，碰撞检测是检测信号电平。以太网取51.2μs为争用期的长度，最短有效帧长64字节，小于64字节视为无效帧，采用二进制指数类型退避算法</td></tr><tr><td>CSMA/CA（载波侦听多路访问/碰撞避免协议）</td><td>广泛用于无线局域网，发送包的同时不能检测到信道上有无冲突，只能尽量避免，采用能量检测、载波检测和能量载波混合检测三种检测信道空闲的方式</td></tr><tr><td>令牌传递协议</td><td>一种轮询访问MAC的协议，适合复杂度很高的广播信道</td></tr><tr><td>后退N帧（GBN）协议</td><td>数据链路层采用的协议，发送方已发送编号为0 - 7的帧，当计时器超时时，若发送方只收到部分帧的确认，需根据此协议规则确定重发帧数</td></tr><tr><td>选择重传协议（SR）</td><td>数据链路层采用的协议，发送方为每个已发送但未确认的帧设置计时器，当某帧超时，仅重传该超时帧</td></tr><tr><td>ZigBee</td><td>新兴的短距离、低速率的无线网络技术，是一种介于无线标记技术和蓝牙之间的技术提案，使用2.4GHz波段，采用跳频技术，可与254个节点联网，基础是IEEE 802.15.4</td></tr></tbody></table><h2 id="数据链路层的服务分类" tabindex="-1">数据链路层的服务分类？ <a class="header-anchor" href="#数据链路层的服务分类" aria-label="Permalink to &quot;数据链路层的服务分类？&quot;">​</a></h2><p>数据链路层通常会根据网络层的需求，提供以下三类差异化的服务模式，具体特点与适用场景如下：</p><ol><li><strong>无确认的无连接服务</strong></li></ol><p>发送端设备无需预先建立链路连接即可直接发送数据帧，接收端设备收到数据后也无需返回确认信息。若传输过程中发生帧丢失，数据链路层不会主动重传，相关问题由上层协议处理。主要用于实时性要求较高或信道误码率极低的通信环境，例如以太网等局域网场景。</p><ol><li><strong>有确认的无连接服务</strong></li></ol><p>发送端设备同样无需提前建立链路连接，但接收端设备在成功接收数据帧后必须返回确认信号。若发送端在规定时间内未收到确认，则会主动重传丢失的帧，以此提升传输可靠性。适用于信道误码率较高的通信环境（如无线通信），通过确认-重传机制弥补信道缺陷。</p><ol><li><strong>有确认的面向连接服务</strong></li></ol><p>数据传输需经历三个明确阶段——链路建立、数据帧传输、链路释放。接收端对每一个接收的帧都需发送确认，发送端仅在收到确认后才会发送下一帧，是可靠性最高的服务模式。该服务中“面向连接”与“确认机制”是强关联的，不存在“无确认的面向连接服务”。适用于对通信可靠性、实时性要求极高的场景（如关键业务数据传输）。</p><h2 id="历年真题" tabindex="-1">历年真题 <a class="header-anchor" href="#历年真题" aria-label="Permalink to &quot;历年真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【国家电网】下列协议中，不属于数据链路层协议的是（ ）A. PPP；B. HDLC；C. ARP；D. TCP答案：D解析：PPP（点到点协议）、HDLC（高级数据链路控制）都是典型的数据链路层协议，用于实现链路建立、数据传输和链路释放等功能。ARP（地址解析协议）虽常被认为与链路层紧密相关，但也属于网络层协议，用于将 IP 地址解析为 MAC 地址。而 TCP（传输控制协议）是传输层协议，提供可靠的面向连接的传输服务</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网（2015）】数据链路层的主要功能不包括（ ）A. 链路管理；B. 路由选择；C. 帧同步；D. 差错控制答案：B解析：数据链路层的主要功能包括链路管理（如链路建立、维护和释放）、帧同步（使接收方能正确识别帧的开始和结束）、差错控制（检测和纠正传输中出现的错误）等。而路由选择是网络层的主要功能，用于确定数据包从源节点到目的节点的路</th></tr></thead></table><table tabindex="0"><thead><tr><th>【中国华电（2024）】数据链路层的主要功能不包括（ ）A. 链路管理B. 路由选择C. 帧同步D. 差错控制答案：B解析：数据链路层的主要功能包括链路管理（如链路建立、维护和释放）、帧同步（使接收方能正确识别帧的开始和结束）、差错控制（检测和纠正传输中出现的错误）等。而路由选择是网络层的主要功能，用于确定数据包从源节点到目的节点的路径。</th></tr></thead></table><h2 id="数据帧" tabindex="-1">数据帧 <a class="header-anchor" href="#数据帧" aria-label="Permalink to &quot;数据帧&quot;">​</a></h2><p>数据帧是数据链路层的基本传输单位，或者说数据在数据链路层上传播的时候是以帧为最小单位的。数据链路层之所以要将比特率组合成帧为单位进行传输，是为了避免当数据传输出错的时候重新发送所有的数据，使用帧之后只需要发送出错的帧就可以了。</p><h2 id="帧的结构" tabindex="-1">帧的结构 <a class="header-anchor" href="#帧的结构" aria-label="Permalink to &quot;帧的结构&quot;">​</a></h2><p><img src="'+e+'" alt=""></p><ol><li><strong>帧头（帧开始符）</strong>：包含了许多控制信息，如目的MAC地址、源MAC地址、帧类型等。目的MAC地址用于标识数据帧的接收方，源MAC地址用于标识发送方，帧类型则指示了帧中数据的协议类型，例如是IP数据包还是ARP请求等。</li><li><strong>数据部分</strong>：承载了来自网络层的数据包，其长度通常有一定的限制，不同的链路层协议对数据部分的长度要求不同。例如，以太网中数据部分的长度一般在46字节到1500字节之间。</li><li><strong>帧尾（帧结束符）</strong>：通常包含用于差错检测的校验序列，如循环冗余校验（CRC）值。接收方通过对帧进行CRC校验，来判断数据在传输过程中是否发生了错误。</li></ol><h2 id="数据帧的作用" tabindex="-1">数据帧的作用 <a class="header-anchor" href="#数据帧的作用" aria-label="Permalink to &quot;数据帧的作用&quot;">​</a></h2><ol><li>**实现数据传输：**网络层的数据封装成帧，通过物理链路传输到目标设备，实现了数据在不同设备之间的传递。</li><li>**提供差错检测：**帧尾的校验序列可以让接收方检测数据在传输过程中是否出现错误，从而保证数据的完整性和准确性。</li><li>**支持链路控制：**帧中的控制字段可以用于实现链路的建立、维护和释放，以及流量控制等功能，确保数据链路的正常运行。</li></ol><h2 id="组帧" tabindex="-1">组帧 <a class="header-anchor" href="#组帧" aria-label="Permalink to &quot;组帧&quot;">​</a></h2><p>通过上面的帧的结构，我们知道了数据帧由“帧头”、“数据”和“帧尾构成”，但是这样组成的帧依然是二进制流数据，为了防止比特流的传输错误，引入了组帧的概念。组帧是指依据一定的规则，将网络层递交下来的分组组合成帧，以便在物理链路上进行传输。通过组帧，数据链路层将网络层的数据转化为适合在物理链路上传输的帧格式，实现了数据的有效封装和传输，并为数据的可靠传输提供了基础。</p><h3 id="字符计数法" tabindex="-1">字符计数法 <a class="header-anchor" href="#字符计数法" aria-label="Permalink to &quot;字符计数法&quot;">​</a></h3><p><img src="'+o+'" alt=""></p><p>在帧头部使用一个字段来标明帧内字符的数量，接收方根据这个字段的值来确定帧的结束位置。但这种方法的缺点是，如果计数字段出现错误，就会导致接收方无法正确判断帧的边界</p><h3 id="带字符填充的首尾定界符法" tabindex="-1">带字符填充的首尾定界符法 <a class="header-anchor" href="#带字符填充的首尾定界符法" aria-label="Permalink to &quot;带字符填充的首尾定界符法&quot;">​</a></h3><p><img src="'+d+'" alt=""></p><p>使用特定的字符作为帧的开始和结束标志，如SOH（Start of Header）作为帧头，EOT（End of Transmission）作为帧尾。为了避免数据中出现与定界符相同的字符而引起误解，需要对数据中的这些字符进行填充，即在这些字符前添加一个转义字符，例如，在PPP协议中就采用了类似的方法 。</p><ul><li>当数据中出现控制字符“SOH”或“EOT”时，在前面插入一个转义字符“ESC”。</li><li>若转义字符也出现在数据当中，则在转义字符前面插入一个转义字符。当接收端收到连续的两个转义字符时，就删除其中前面的一个</li></ul><h3 id="零比特填充的首尾标志法-常用" tabindex="-1">零比特填充的首尾标志法(常用) <a class="header-anchor" href="#零比特填充的首尾标志法-常用" aria-label="Permalink to &quot;零比特填充的首尾标志法(常用)&quot;">​</a></h3><p><img src="'+n+'" alt=""></p><p>零比特填充法会以一个特定的位模式作为帧的开始和结束标志，如01111110。为了避免数据中出现与标志位模式相同的位串，当数据中出现连续的5个1时，就在其后自动插入一个0。接收方在接收数据时，会自动删除这些插入的0。这种方法常用于HDLC协议等：</p><ul><li>原理 ：允许数据帧包含任意数量的比特，且支持任意字符编码（每个字符的编码比特数不限）。</li><li>发送端操作 ：在信息位中若遇到连续5个“1”，会自动在其后插入一个“0”，避免数据中出现与帧标志（01111110）相同的比特流（即连续6个“1”会被拆分为5个“1”+“0”）。</li><li>接收端操作 ：接收时每检测到连续5个“1”，会删除其后紧跟的“0”，恢复原始数据。</li><li>优势 ：硬件实现简单，性能优于字符填充法，能有效保证数据传输的透明性（即数据中可包含任意比特组合）。</li></ul><h3 id="违规编码法" tabindex="-1">违规编码法 <a class="header-anchor" href="#违规编码法" aria-label="Permalink to &quot;违规编码法&quot;">​</a></h3><p>该方法依赖物理层的冗余编码技术，通过“违规编码序列”定界帧的起止，具体特点如下：</p><ul><li>原理 ：物理层编码时，部分编码序列被定义为“违规”（即正常数据不会使用），借用这些违规序列作为帧的起始或结束标志。</li><li>示例 ：以曼彻斯特编码为例，数据“1”编码为“高-低”电平对，“0”编码为“低-高”电平对，而“高-高”和“低-低”电平对属于违规编码（正常数据不使用），可用于标识帧的边界。</li><li>优势 ：无需额外的填充技术（如字符填充或零比特填充），直接通过物理层编码特性实现数据透明传输。</li><li>局限性 ：仅适用于采用冗余编码的物理层环境（如IEEE 802局域网标准）。</li></ul><h3 id="组帧的步骤" tabindex="-1">组帧的步骤 <a class="header-anchor" href="#组帧的步骤" aria-label="Permalink to &quot;组帧的步骤&quot;">​</a></h3><ol><li><strong>添加帧头和帧尾</strong>：根据所采用的组帧方法，在要发送的数据前后分别添加相应的帧头和帧尾。帧头中通常包含目的地址、源地址、帧类型等控制信息，帧尾一般包含用于差错检测的校验序列，如CRC校验码。</li><li><strong>填充数据（如果需要）</strong>：如果采用带字符填充或带位填充的方法，需要对数据部分进行检查和填充，以确保数据中不会出现与定界符或标志位模式相同的内容，避免帧边界判断错误。</li><li><strong>计算校验码</strong>：根据帧中的数据部分，使用特定的算法（如CRC算法）计算出校验码，并将其填入帧尾的相应字段。接收方可以通过同样的算法对接收的数据进行校验，以判断数据在传输过程中是否发生错误。</li></ol><h2 id="历年真题-1" tabindex="-1">历年真题 <a class="header-anchor" href="#历年真题-1" aria-label="Permalink to &quot;历年真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【国家电网】数据链路层传输的数据单位是（ ）A. 比特；B. 帧；C. 分组；D. 报文答案：B解析：数据链路层以帧为单位传输数据，将网络层传来的分组封装成帧，添加帧头和帧尾信息，实现对数据的可靠传输。比特是物理层传输单位；分组是网络层传输单位；报文是传输层及以上层次的概念</th></tr></thead></table><h2 id="差错控制" tabindex="-1">差错控制 <a class="header-anchor" href="#差错控制" aria-label="Permalink to &quot;差错控制&quot;">​</a></h2><p>差错控制是数据通信中用于保证数据传输准确性的重要技术，通过检错编码和纠错编码来实现。以下是对检错编码中的水平 / 垂直奇偶校验码、循环冗余校验（CRC）以及纠错编码中的海明码的介绍。</p><h2 id="检错编码" tabindex="-1">检错编码 <a class="header-anchor" href="#检错编码" aria-label="Permalink to &quot;检错编码&quot;">​</a></h2><p>检错编码是一种能够发现数据传输过程中是否出现错误的编码方式。它通过在原始数据上附加一些冗余信息（校验码），使得接收方可以根据这些冗余信息来判断接收到的数据是否有误。</p><p>发送方将原始数据按照一定的规则进行编码，生成包含校验码的数据帧并发送出去。接收方收到数据帧后，按照相同的规则对接收到的数据进行校验。如果校验结果表明数据存在错误，接收方会要求发送方重新发送数据。常见的检错编码有奇偶校验码、循环冗余校验（CRC）码等。</p><p>检错编码的实现相对简单，主要作用是快速发现数据传输中的错误，但不能自动纠正错误，需要借助重传机制来保证数据的准确性。</p><h2 id="水平-垂直奇偶校验码" tabindex="-1">水平/垂直奇偶校验码 <a class="header-anchor" href="#水平-垂直奇偶校验码" aria-label="Permalink to &quot;水平/垂直奇偶校验码&quot;">​</a></h2><p>奇偶校验码是一种通过在数据位后添加一位奇偶校验位来使整个数据码字中 “1” 的个数为奇数或偶数的编码方式。水平奇偶校验是对每一行数据进行奇偶校验，垂直奇偶校验则是对每一列数据进行奇偶校验。实现简单，能够检测出奇数个错误，但对于偶数个错误可能无法检测出来，检错能力有限。</p><p>偶校验码是一种最为简单的校验码，它用来检测数据传输过程中是否发生错误,奇偶校验码的组成：n-1 位信息位 + 1 位校验位,两种校验方法：奇校验和偶校验。</p><h2 id="循环冗余校验——crc" tabindex="-1">循环冗余校验——CRC <a class="header-anchor" href="#循环冗余校验——crc" aria-label="Permalink to &quot;循环冗余校验——CRC&quot;">​</a></h2><p>循环冗余校验，（CRC 是Cyclic Redundancy Check），用于校验数据传输的完整性。 一般情况下在数据发送前计算CRC校验值，附在发送数据之后，数据接收方也按照同样方法计算CRC，然后对比计算结果，如果一致说明数据数据传输无误，否则数据传输出错。</p><p>原理简单来说就是发送方和接收方约定一个生成多项式，发送方将待发送的数据作为被除数，作为除数，进行模2除法运算，得到的余数作为校验码附加在数据后面一起发送。接收方收到数据后，用同样的生成多项式进行校验，若余数为0，则认为数据传输正确，否则表示数据有误。</p><p>循环冗余校验码具有检错能力强，能够检测出多种类型的错误，包括突发错误，并且实现相对简单，易于硬件实现，因此在数据通信和存储中得到了广泛应用。</p><h3 id="模二除法" tabindex="-1">模二除法 <a class="header-anchor" href="#模二除法" aria-label="Permalink to &quot;模二除法&quot;">​</a></h3><p>CRC计算采用二进制模二除法，这里简单介绍下，模二除法的特点是<strong>对应位相同为0，不同为1（不借位）</strong>，直接举例说明。</p><p><img src="'+s+'" alt=""></p><h3 id="crc计算实例" tabindex="-1">CRC计算实例 <a class="header-anchor" href="#crc计算实例" aria-label="Permalink to &quot;CRC计算实例&quot;">​</a></h3><p>CRC校验，在发送端会先把数据划分成为组，每组m个比特位。现在假设发送的数据D=101101（m=6），发送端和接收端规定的除数P=1101（也可以写作）。</p><p>第一步：现在101101后面添加0，0的个数是<strong>除数的位数减1</strong>，本例的除数个数是4，所以后面添加0的个数是3，所以最终被除数的结果是101101000。<strong>CRC运算就是在数据D的后面添加供差错校验的n位冗余码，然后构成一个帧发送出去，一共发送m+n位。</strong></p><p>第二步：进行模二除法运算</p><p><img src="'+h+'" alt=""></p><p>得到余数为010，将其作为冗余码添加在数据D的后面，所以在信道传输的数据是101101010.</p><p>第三步：接收端接收到数据之后，采用同样的方法去校验数据的正确性，除数不变还是1101。<strong>如果余数为0则说明传输的数据正确；如果不为0，则说明传输的数据存在错误</strong>，具体校验过程如下图。</p><p><img src="'+b+'" alt=""></p><table tabindex="0"><thead><tr><th>【例题】在数据传输过程中，若接收方收到的二进制比特序列为 10110011010，CRC 校验生成多项式为 。（1）二进制比特序列在传输中是否出现了差错？（2）若无差错，则发送方发送的二进制比特序列和 CRC 校验码的比特序列分别是什么？若有差错，则指出发送方发送的二进制比特序列和 CRC 校验码的比特序列分别为多少位。【解】多项式 G(x) = 11001，进行模 2 除法：10110011010 除以 11001，所得余数为 0，说明二进制比特序列在传输中没有出现差错。因为 G(x) 的 r = 4，所以发送数据的比特序列为 1011001，CRC 校验码为 1010。</th></tr></thead></table><h2 id="纠错编码——海明码" tabindex="-1">纠错编码——海明码 <a class="header-anchor" href="#纠错编码——海明码" aria-label="Permalink to &quot;纠错编码——海明码&quot;">​</a></h2><p>海明码是一种能够纠正一位错误的纠错编码，它通过在数据位中插入若干个校验位，使得校验位和数据位之间满足一定的逻辑关系，从而可以根据这些关系检测和纠正错误。具体来说，海明码将数据位按照一定的规则分组，每个校验位负责校验一组数据位，通过对这些校验位的计算和比较，可以确定错误的位置并进行纠正。</p><p>海明码具有较强的纠错能力，能够自动纠正一位错误，同时还能检测出两位错误。但随着数据位数的增加，校验位的数量也会相应增加，编码效率会有所降低。</p><h2 id="历年真题-2" tabindex="-1">历年真题 <a class="header-anchor" href="#历年真题-2" aria-label="Permalink to &quot;历年真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【中国铁塔（2021）】从差错控制角度看，当信道中加性干扰主要是高斯白噪声时，这种信道通常被称为（）。A. 混合信道B. 突发信道C. 干扰信道D. 随机信道答案 ：C</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国电电网（2017）】在数据链路层中，CRC 校验码主要用于（ ）A. 流量控制B. 拥塞控制C. 差错检测D. 加密解密答案：C解析：CRC（循环冗余校验）是一种常用的差错检测技术，通过在发送端根据要发送的数据生成校验码，接收端利用相同的算法对收到的数据进行校验，判断数据在传输过程中是否发生错误。流量控制主要用于调节发送方和接收方的数据传输速率；拥塞控制是网络层和传输层处理网络拥塞的机制；加密解密涉及数据的安全保护，与 CRC 校验码功能不同。</th></tr></thead></table><h2 id="数据链路层设备" tabindex="-1">数据链路层设备 <a class="header-anchor" href="#数据链路层设备" aria-label="Permalink to &quot;数据链路层设备&quot;">​</a></h2><h2 id="网桥" tabindex="-1">网桥 <a class="header-anchor" href="#网桥" aria-label="Permalink to &quot;网桥&quot;">​</a></h2><h3 id="网桥概念" tabindex="-1">网桥概念 <a class="header-anchor" href="#网桥概念" aria-label="Permalink to &quot;网桥概念&quot;">​</a></h3><p><img src="'+C+'" alt=""></p><p>网桥是一种在数据链路层实现局域网互连的设备，它能够连接两个或多个局域网网段，对帧进行存储、转发和过滤。网桥会根据 MAC 地址来转发帧，将收到的帧从一个网段转发到另一个网段，使得不同网段之间的设备能够进行通信，就好像这些设备在同一个局域网中一样。</p><h3 id="网桥工作原理" tabindex="-1">网桥工作原理 <a class="header-anchor" href="#网桥工作原理" aria-label="Permalink to &quot;网桥工作原理&quot;">​</a></h3><p>网桥通过检查帧的目的MAC地址，并根据自己维护的MAC地址表来决定是否转发该帧。只有当目的MAC地址在另一个网段时，网桥才会转发帧</p><p>网桥的MAC地址表是通过自学习过程建立的，当网桥收到一个帧时，它会记录帧的源MAC地址和接收端口，从而逐渐学习到各个设备的MAC地址和所在网段</p><h3 id="网桥的优点" tabindex="-1">网桥的优点 <a class="header-anchor" href="#网桥的优点" aria-label="Permalink to &quot;网桥的优点&quot;">​</a></h3><ol><li>过滤通信量 ：网桥可以减少局域网中的广播流量，提高网络的性能和效率</li><li>扩大网络物理范围 ：通过连接多个局域网网段，网桥能够扩大网络的覆盖范围</li><li>提高可靠性 ：当网络中某个网段出现故障时，网桥可以自动隔离故障网段，避免故障影响到其他网段</li><li>限制冲突域范围 ：网桥可以将一个大的局域网分割成多个较小的冲突域，减少冲突的发生</li></ol><h3 id="网桥的缺点" tabindex="-1">网桥的缺点 <a class="header-anchor" href="#网桥的缺点" aria-label="Permalink to &quot;网桥的缺点&quot;">​</a></h3><ol><li>增加时延 ：网桥需要对帧进行存储和转发，会增加一定的时延</li><li>MAC子层没有流量控制功能 ：可能导致网络拥塞</li><li>只适合于用户数不多和通信量不太大的局域网 ：否则可能会因传播过多的广播信息而产生网络拥塞，即广播风暴</li></ol><h2 id="交换机" tabindex="-1">交换机 <a class="header-anchor" href="#交换机" aria-label="Permalink to &quot;交换机&quot;">​</a></h2><h3 id="以太网交换机" tabindex="-1">以太网交换机 <a class="header-anchor" href="#以太网交换机" aria-label="Permalink to &quot;以太网交换机&quot;">​</a></h3><p><img src="'+c+'" alt=""></p><p><strong>交换机</strong>是一种工作在数据链路层的网络设备，它能够根据以太网帧中的目的 MAC 地址，将帧从一个端口转发到另一个端口，实现多个以太网设备之间的高速数据交换 。从本质上来说交换机与网桥属同一类设备，都工作在数据链路层。从本质上说，以太网交换机就是一个多端口的网桥，能连接多个网段，降低组网成本，为每个工作站提供更高带宽 。</p><h3 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h3><ol><li><strong>学习阶段</strong>：交换机刚加电启动时，MAC地址表为空。当收到帧时，它会检查帧的源MAC地址，并将该地址与接收帧的端口号对应起来，添加到MAC地址表中，从而学习到连接在各个端口上的设备的MAC地址 。</li><li><strong>转发阶段</strong>：收到帧后，交换机检查帧的目的MAC地址，并在MAC地址表中查找对应的端口号。若找到匹配端口，则将帧从该端口转发出去；若未找到，则将帧从除接收端口外的所有其他端口广播出去，以寻找目的设备。当目的设备响应时，交换机学习到其MAC地址并添加到MAC地址表中，以便后续帧能直接转发到目的端口 。</li><li><strong>更新阶段</strong>：MAC地址表中的条目有生存时间（TTL），若一段时间内未收到来自某个MAC地址的帧，交换机将自动删除该条目，以保证MAC地址表中的信息始终反映网络中设备的实际连接情况 。</li></ol><h3 id="转发方式" tabindex="-1">转发方式 <a class="header-anchor" href="#转发方式" aria-label="Permalink to &quot;转发方式&quot;">​</a></h3><ol><li><strong>直通式</strong>：交换机在接收到帧的目的MAC地址后，立即开始转发帧，无需等待整个帧被接收和处理。优点是转发速度快、延迟小，但无法检测帧中的错误，可能会转发错误帧 。</li><li><strong>存储转发式</strong>：先将整个帧接收并存储在缓冲区中，然后对帧进行错误检测和处理，确认无误后才根据目的MAC地址进行转发。优点是能检测和丢弃错误帧，但转发延迟相对较大 。</li><li><strong>无碎片直通式</strong>：接收帧时，先检查帧的前64字节（以太网中小于64字节的帧通常是冲突产生的碎片）。若前64字节无错误，则开始转发帧；否则丢弃该帧。这种模式结合了直通式和存储转发式的优点，既能减少转发延迟，又能避免转发碎片帧 。</li></ol><h3 id="交换机特点与优势" tabindex="-1">交换机特点与优势 <a class="header-anchor" href="#交换机特点与优势" aria-label="Permalink to &quot;交换机特点与优势&quot;">​</a></h3><ol><li><strong>端口与连接</strong>：每个端口直接与单个主机相连（普通网桥端口往往连接到以太网的一个网段），且一般工作在全双工方式 。</li><li><strong>冲突域隔离</strong>：通过内部的交换矩阵把网络划分为多个网段，每个端口为一个冲突域，能同时连通许多对端口，使每对相互通信的主机都能像独占通信媒体那样无碰撞地传输数据 。</li><li><strong>即插即用</strong>：与透明网桥一样，是即插即用设备，其内部的帧的转发表通过自学习算法自动逐渐建立 。</li><li><strong>高速交换</strong>：使用专用的交换结构芯片，交换速率较高，独占传输媒体的带宽 。</li><li><strong>应用场景</strong>：适用于作为LAN核心主干连接设备（如网络中心、数据中心等）、网络通信流量很大的应用场合（如图像处理、视频流等）以及对网络响应速度要求较高的场合 。</li></ol><h2 id="历年真题-3" tabindex="-1">历年真题 <a class="header-anchor" href="#历年真题-3" aria-label="Permalink to &quot;历年真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【国家电网（2018年）】扩展局域网时，以下哪个设备工作在数据链路层？A. 交换机；B. 中继器；C. 路由器；D. 集线器答案：A</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网（2021年）】（专业多项选择题）以下关于网络层和数据链路层联网设备的描述，正确的是？A. 网络层的联网设备是路由器；B. 数据链路层的联网设备是网桥和交换机；C. 传输层和会话层主要是软件功能，都不需要专用的联网设备；D. 以上都不对答案：ABC</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网（2014年）】二层交换机工作在OSI模型的（ ）层。A. 物理层；B. 数据链路层；C. 网络层；D. 传输层答案：B</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网（2014年）】以下说法错误的是（ ）A. 中继器是工作在物理层的设备；B. 集线器和以太网交换机工作在数据连路层；C. 路由器是工作在网络层的设备；D. 网桥能隔离网络层广播答案：BD</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网（2016年）】以太网交换机进行转发决策时使用的PDU地址是（ ）A. 目的物理地址；B. 目的IP地址；C. 源物理地址；D. 源IP地址答案：A</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网（2023年）】以下关于网络层次与主要设备对应关系的叙述中，配对正确的是（ ）A. 网络层——集线器；B. 数据链路层——网桥；C. 传输层——路由器；D. 会话层——防火墙答案：B</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网（2020年）】下列对交换机的描述中，正确的是（ ）A. 交换机根据接收数据包括中的IP地址过滤和转发数据；B. 交换机可将多台数据终端设备连接在一起，构成星状结构的网络；C. 交换机有存储转发快速转发和碎片丢弃三种交换模式；D. 交换机允许多对站点进行并发通信答案：BCD</th></tr></thead></table><h2 id="数据链路层协议" tabindex="-1">数据链路层协议 <a class="header-anchor" href="#数据链路层协议" aria-label="Permalink to &quot;数据链路层协议&quot;">​</a></h2><p><img src="'+g+'" alt=""></p><h2 id="ppp协议-点对点协议" tabindex="-1">PPP协议（点对点协议） <a class="header-anchor" href="#ppp协议-点对点协议" aria-label="Permalink to &quot;PPP协议（点对点协议）&quot;">​</a></h2><h3 id="ppp协议概念" tabindex="-1">PPP协议概念 <a class="header-anchor" href="#ppp协议概念" aria-label="Permalink to &quot;PPP协议概念&quot;">​</a></h3><p>PPP（Point - to - Point Protocol）即点到点协议，是为在同等单元之间传输数据包这样的简单链路设计的链路层协议。它主要用于在串行链路（如电话线、串口等）上建立、配置和测试数据链路连接，为网络层协议提供承载服务，使得不同类型的网络层协议（如 IP、IPX 等）能够在点到点的链路上进行传输。PPP 协议具有多种功能，如支持多种网络层协议、提供链路控制和网络控制功能、支持身份验证等，是目前广域网中使用最广泛的链路层协议之一。</p><h3 id="ppp协议组成" tabindex="-1">PPP协议组成 <a class="header-anchor" href="#ppp协议组成" aria-label="Permalink to &quot;PPP协议组成&quot;">​</a></h3><ol><li>链路控制协议（LCP），主要用于建立、配置、维护和终止点到点的链路连接。它负责协商链路的参数，如最大传输单元（MTU）、认证方式等，还能检测链路的状态，当链路出现故障时进行相应的处理。</li><li>网络控制协议（NCP），PPP 协议可以支持多种网络层协议，不同的网络层协议有对应的 NCP。例如，IP 控制协议（IPCP）用于配置和管理 IP 协议相关的参数，如分配 IP 地址等；IPX 控制协议（IPXCP）则用于处理 IPX 协议的相关配置。NCP 的作用是在链路建立后，对特定的网络层协议进行配置和协商，使得网络层协议能够在链路上正常运行。</li><li>扩展协议，PPP 协议还包括一些扩展协议，如用于身份验证的 PAP（Password Authentication Protocol，密码认证协议）和 CHAP（Challenge - Handshake Authentication Protocol，挑战握手认证协议）等。这些扩展协议为 PPP 协议提供了额外的功能，增强了协议的安全性和适用性。</li></ol><h3 id="ppp协议帧格式" tabindex="-1">PPP协议帧格式 <a class="header-anchor" href="#ppp协议帧格式" aria-label="Permalink to &quot;PPP协议帧格式&quot;">​</a></h3><p><img src="'+p+'" alt=""></p><table tabindex="0"><thead><tr><th>字段</th><th>描述</th></tr></thead><tbody><tr><td>标志字段（Flag）</td><td>占 1 个字节，值为 0x7E，用于标识帧的开始和结束。</td></tr><tr><td>地址字段（Address）</td><td>占 1 个字节，通常取值为 0xFF，表示广播地址。PPP 协议不使用该字段来标识特定的目的地址，而是通过其他方式来确定数据的接收方。</td></tr><tr><td>控制字段（Control）</td><td>占 1 个字节，一般取值为 0x03，表示无编号帧，用于承载 PPP 协议的各种控制信息和数据。</td></tr><tr><td>协议字段（Protocol）</td><td>占 2 个字节，用于标识帧中数据字段所承载的协议类型。例如，0x0021 表示 IP 协议，0xC021 表示链路控制协议（LCP），0x8021 表示网络控制协议（NCP）等。</td></tr><tr><td>数据字段（Data）</td><td>长度可变，用于承载网络层协议的数据或 PPP 协议的控制信息，其长度由 MTU（最大传输单元）和协议字段所标识的协议类型决定。</td></tr><tr><td>帧校验序列字段（FCS）</td><td>占 2 个字节或 4 个字节（取决于配置），用于检测帧在传输过程中是否发生错误。它是根据帧中除标志字段以外的其他字段计算得到的循环冗余校验码（CRC）。</td></tr></tbody></table><h2 id="csma协议" tabindex="-1">CSMA协议 <a class="header-anchor" href="#csma协议" aria-label="Permalink to &quot;CSMA协议&quot;">​</a></h2><h3 id="csma-cd协议-载波侦探-冲突检测" tabindex="-1">CSMA/CD协议（载波侦探，冲突检测） <a class="header-anchor" href="#csma-cd协议-载波侦探-冲突检测" aria-label="Permalink to &quot;CSMA/CD协议（载波侦探，冲突检测）&quot;">​</a></h3><p><img src="'+u+'" alt=""></p><p>CSMA/CD协议（Carrier Sense Multiple Access with Collision Detection）是对总线型拖补结构的以太网进行访问控制的协议，尽最大努力的交付，即不可靠的交付，CSMA协议的特点是：<strong>先听先发，边发边听，碰撞停发，随机延迟后重发。</strong></p><ol><li>载波监听：每个节点在发送数据之前，都要持续监听信道。通过监听，节点可以判断信道上是否有其他节点正在发送数据。若信道忙（有载波信号），则等待；若信道空闲，则可以发送数据。</li><li>冲突检测：在发送数据的过程中，节点同时检测信道上的信号。如果检测到的信号电压变化幅度超过了正常发送信号的幅度，就说明发生了冲突。这是因为当两个或多个节点同时发送数据时，信号会在信道上叠加，导致信号幅度异常。</li><li>冲突处理：一旦检测到冲突，发送节点会立即停止发送数据，并发送一个简短的阻塞信号，以确保网络中的其他节点都能知道发生了冲突。然后，每个参与冲突的节点会进入退避阶段，等待一段随机时间后再次尝试发送数据。退避时间通常根据截断二进制指数退避算法来确定，该算法可以使冲突的节点以不同的概率选择退避时间，从而减少再次冲突的可能性。</li></ol><p>CSMA/CD协议主要用于有线以太网，包括传统共享式以太网（如集线器连接）和早期交换式以太网（交换机半双工模式）。现代交换式以太网多采用全双工模式，设备独占信道，无冲突风险，因此 CSMA/CD 已不再启用，但仍是以太网协议的基础定义。</p><h3 id="csma-ca协议-载波侦听-冲突避免" tabindex="-1">CSMA/CA协议（载波侦听，冲突避免） <a class="header-anchor" href="#csma-ca协议-载波侦听-冲突避免" aria-label="Permalink to &quot;CSMA/CA协议（载波侦听，冲突避免）&quot;">​</a></h3><p>CSMA/CA（Carrier Sense Multiple Access with Collision Avoidance，<strong>载波监听多路访问 / 冲突避免</strong>）是一种用于无线通信网络的介质访问控制（MAC）协议，核心目标是<strong>在多设备共享无线信道时，通过 “避免冲突” 而非 “检测冲突” 来提升信道利用率</strong>。它是 IEEE 802.11 协议族（即 WiFi）的核心 MAC 机制，之所以不采用有线网络的 CSMA/CD（冲突检测），本质是由无线信道的特殊性决定的。CSMA/CA协议主要广泛应用于：</p><ul><li>家庭 / 企业 WiFi 网络（手机、电脑、智能家居设备接入）；</li><li>公共无线局域网（如商场、机场的免费 WiFi）；</li><li>工业无线局域网（如 802.11ah 用于物联网设备）。</li></ul><h4 id="为什么采用冲突避免-而非检测" tabindex="-1">为什么采用冲突避免，而非检测？ <a class="header-anchor" href="#为什么采用冲突避免-而非检测" aria-label="Permalink to &quot;为什么采用冲突避免，而非检测？&quot;">​</a></h4><p><img src="'+P+'" alt=""></p><p>有线网络（如以太网）中，设备可通过<strong>CSMA/CD</strong>实时检测信道上的信号叠加（冲突），一旦检测到冲突就立即停止发送并退避。但无线信道存在两个关键问题，导致 “冲突检测” 不可行：</p><ol><li>**隐藏站问题（Hidden Terminal Problem）**设备 A 和设备 C 均在设备 B 的通信范围内，但 A 与 C 彼此不在对方的覆盖范围。当 A 向 B 发送数据时，C 无法 “监听” 到 A 的信号，若 C 同时向 B 发送数据，就会在 B 处产生冲突，但 A 和 C 都无法检测到冲突（因两者无直接信号交互）。</li><li>**暴露终端问题（Exposed Terminal Problem）**设备 A 在设备 B 的覆盖范围，设备 C 也在 B 的覆盖范围，但 A 与 C 不在彼此覆盖范围。当 B 向 A 发送数据时，C 会 “监听” 到 B 的信号，误以为信道忙而不敢向其他设备（如 D，与 C 相邻但与 B 不相邻）发送数据，导致信道资源浪费（实际 C 向 D 发送不会与 B-A 的通信冲突）。</li></ol><p>此外，无线设备的<strong>发送功率远大于接收功率</strong>，若设备同时发送和接收信号，接收端会被自身发送信号淹没，无法检测其他设备的信号冲突。因此，无线网络必须放弃 “冲突检测”，转向 “冲突避免”—— 这正是 CSMA/CA 的设计核心。</p><h4 id="csma-ca-的核心工作原理与流程" tabindex="-1">CSMA/CA 的核心工作原理与流程 <a class="header-anchor" href="#csma-ca-的核心工作原理与流程" aria-label="Permalink to &quot;CSMA/CA 的核心工作原理与流程&quot;">​</a></h4><p>CSMA/CA 通过 “<strong>载波监听→退避机制→握手确认</strong>” 三步核心逻辑，最大限度避免冲突，具体流程可分为以下步骤：</p><p>Sense）—— 判断信道是否空闲</p><p>设备在发送数据前，会先通过<strong>空闲信道评估（CCA，Clear Channel Assessment）</strong> 检测信道状态，CCA 包含两种方式：</p><ul><li><strong>物理载波监听</strong>：直接检测信道上是否有其他设备的射频信号（如信号强度是否超过阈值），若有则判定信道 “忙”。</li><li><strong>虚拟载波监听</strong>：通过接收其他设备发送的 “控制帧”（如 RTS、CTS、ACK）中的 “网络分配向量（NAV，Network Allocation Vector）” 来判断信道忙闲。NAV 会标注 “信道将被占用的时间”，设备即使未直接监听到射频信号，也会根据 NAV 值等待信道空闲。</li></ul><p>若 CCA 检测到信道 “空闲” 且持续一段时间（称为<strong>分布式帧间间隔 DIFS，Distributed Inter-Frame Space</strong>，用于优先级控制），设备进入下一步；若信道 “忙”，则持续监听直至信道空闲并等待 DIFS。</p><p>避免 “同时发送” 冲突</p><p>即使多个设备同时检测到信道空闲，若它们立即发送数据，仍会产生冲突。因此 CSMA/CA 引入<strong>二进制指数退避算法（Binary Exponential Backoff，BEB）</strong> ，让设备随机延迟发送，规则如下：</p><ol><li>每个设备维护一个 “退避计数器”，初始值为 0。</li><li>当设备首次检测到信道空闲并等待 DIFS 后，若仍无其他设备发送，退避计数器开始倒计时（倒计时期间持续监听信道）。</li><li>退避计数器的初始 “竞争窗口（CW，Contention Window）” 大小为固定值（如 802.11b 中，初始 CW=31 个时槽），设备从 [0, CW] 中随机选择一个数作为退避计数器的初始值。</li><li>若倒计时期间信道被其他设备占用，退避计数器暂停，待信道再次空闲并等待 DIFS 后，继续倒计时。</li><li>若退避计数器减至 0 时信道仍空闲，设备立即发送数据；若发送失败（未收到 ACK），则将 CW 翻倍（指数增长，如 31→63→127...），重新进入退避流程，直至 CW 达到最大阈值（如 1023）或发送成功。</li></ol><p>退避机制的核心是 “<strong>随机延迟</strong>”，通过引入随机性减少多设备同时发送的概率，从根源上避免冲突。</p><p>确保通信成功</p><p>无线信道存在信号衰减、干扰等问题，即使避免了冲突，数据也可能丢失。因此 CSMA/CA 引入 “<strong>确认机制</strong>”：</p><ul><li>发送方发送数据帧后，会等待一个 “短帧间间隔（SIFS，Short Inter-Frame Space）”（SIFS&lt;DIFS，优先级更高，确保接收方优先响应）。</li><li>接收方成功接收数据帧后，会在 SIFS 后立即发送一个 “确认帧（ACK）” 给发送方。</li><li>若发送方在规定时间内未收到 ACK（可能是冲突或数据丢失），则判定发送失败，触发退避机制重新发送。</li></ul><p>握手 —— 解决隐藏终端问题</p><p>对于长度较长的数据帧，若发生冲突，重传开销较大。CSMA/CA 可通过 “<strong>请求发送（RTS，Request To Send）/ 允许发送（CTS，Clear To Send）</strong> ” 握手机制进一步降低冲突风险，流程如下：</p><ol><li>发送方（如 A）先发送一个短的 RTS 帧，包含 “数据帧长度” 和 “NAV 值”（告知其他设备信道将被占用的时间）。</li><li>接收方（如 B）收到 RTS 后，在 SIFS 后发送 CTS 帧，同样包含 NAV 值，覆盖范围与 RTS 一致。</li><li>所有监听到 RTS 或 CTS 的设备，会根据 NAV 值标记信道 “忙”，在 NAV 期间不发送数据。</li><li>发送方 A 收到 CTS 后，在 SIFS 后发送数据帧；接收方 B 收到数据后，发送 ACK 确认。</li></ol><p>RTS/CTS 通过 “提前预约信道”，让隐藏终端（如 C）也能通过 NAV 知道信道被占用，从而避免冲突。但 RTS/CTS 会增加额外的控制帧开销，因此通常仅在数据帧较长时启用（短帧启用反而降低效率）。</p><h3 id="csma-ca协议和csma-cd协议的区别" tabindex="-1">CSMA/CA协议和CSMA/CD协议的区别？ <a class="header-anchor" href="#csma-ca协议和csma-cd协议的区别" aria-label="Permalink to &quot;CSMA/CA协议和CSMA/CD协议的区别？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比维度</th><th>CSMA/CD 协议</th><th>CSMA/CA 协议</th></tr></thead><tbody><tr><td>应用场景与传输介质</td><td>有线局域网（总线型以太网），依赖双绞线、同轴电缆等有线介质</td><td>无线网络（Wi-Fi、ZigBee），适用于2.4GHz/5GHz频段等无线介质</td></tr><tr><td>冲突处理机制</td><td>碰撞检测：边发送边监听，检测到冲突立即停止并发送拥塞信号，随后重传</td><td>碰撞避免：发送前通过RTS/CTS握手预约信道，发送后等待ACK确认，未收到则重传</td></tr><tr><td>载波检测方式</td><td>检测电缆中电压变化判断冲突</td><td>能量检测（ED）、载波检测（CS）、能量载波混合检测三种方式</td></tr><tr><td>效率与现代应用</td><td>高负载网络中冲突频繁，带宽浪费严重，随全双工交换式以太网普及，应用逐渐减少</td><td>无线网络中稳定性更高，高拥挤场景下因等待/侦听机制增加延迟，是无线主流协议</td></tr><tr><td>可靠性机制</td><td>依赖冲突检测与退避算法，无确认机制</td><td>通过ACK确认、RTS/CTS预约、虚拟载波监听（NAV）实现高可靠性</td></tr><tr><td>退避算法</td><td>截断二进制指数退避算法，冲突次数增加时退避窗口加倍（最大10次）</td><td>二进制指数退避算法（DCF），冲突后随机选择退避时间</td></tr></tbody></table><h2 id="hdlc协议" tabindex="-1">HDLC协议 <a class="header-anchor" href="#hdlc协议" aria-label="Permalink to &quot;HDLC协议&quot;">​</a></h2><p><img src="'+A+'" alt=""></p><p><strong>HDLC（高级数据链路控制）协议</strong>是一种面向比特型的同步协议，用于实现链路建立、数据传输和链路释放等功能，能保证传送到下一层的数据在传输过程中准确接收，还能实现流量控制。</p><ol><li><strong>HDLC协议的特点</strong></li></ol><ul><li><strong>面向比特</strong>：HDLC协议采用比特填充法实现透明传输，允许数据帧包含任意数量的比特，且支持任意字符编码（每个字符的编码比特数不限）。</li><li><strong>同步协议</strong>：HDLC协议是一种同步协议，使用特定的位模式（如01111110）作为帧的开始和结束标志，通过零比特填充法避免数据中出现与标志位模式相同的位串。</li><li><strong>可靠性高</strong>：HDLC协议通过差错检测和纠正机制，如循环冗余校验（CRC）、海明码等，检测和纠正传输过程中出现的错误，确保数据的准确性。</li><li><strong>流量控制</strong>：HDLC协议通过流量控制机制，如停止等待协议、滑动窗口协议等，使发送方的发送速度与接收方的接收速度相匹配，避免数据丢失。</li></ul><ol><li><strong>HDLC协议的帧结构</strong></li></ol><ul><li><strong>标志字段</strong>：HDLC协议的帧以特定的位模式（如01111110）作为帧的开始和结束标志，用于标识帧的边界。</li><li><strong>地址字段</strong>：用于标识帧的接收方或发送方的地址。</li><li><strong>控制字段</strong>：用于控制帧的类型和操作，如数据帧、命令帧、响应帧等。</li><li><strong>信息字段</strong>：承载了来自网络层的数据包，其长度通常有一定的限制。</li><li><strong>帧校验序列（FCS）</strong>：用于差错检测的校验序列，如循环冗余校验（CRC）值。</li></ul><ol><li><strong>HDLC协议的工作模式</strong></li></ol><ul><li><strong>正常响应模式（NRM）</strong>：主站向从站发送命令，从站在收到命令后向主站发送响应。</li><li><strong>异步响应模式（ARM）</strong>：从站可以在没有主站命令的情况下向主站发送数据帧。</li><li><strong>异步平衡模式（ABM）</strong>：每个站都可以作为主站或从站，无需主站的命令即可发送数据帧。</li></ul><ol><li><strong>HDLC协议的应用场景</strong></li></ol><ul><li><strong>广域网</strong>：HDLC协议是目前广域网中使用最广泛的链路层协议之一，常用于在串行链路（如电话线、串口等）上建立、配置和测试数据链路连接。</li><li><strong>局域网</strong>：HDLC协议也可用于局域网中，如在令牌环网中使用HDLC协议进行数据传输。</li></ul><h2 id="arq协议-自动请求重传协议" tabindex="-1">ARQ协议（自动请求重传协议） <a class="header-anchor" href="#arq协议-自动请求重传协议" aria-label="Permalink to &quot;ARQ协议（自动请求重传协议）&quot;">​</a></h2><p><strong>ARQ（Automatic Repeat reQuest）协议</strong>是一种错误纠正协议，主要工作在数据链路层和传输层，通过确认和超时机制在不可靠服务基础上实现可靠信息传输。以下是其详细介绍：</p><ol><li><strong>自动重传请求（ARQ）协议的定义</strong>：</li></ol><p>ARQ是一种错误纠正协议，通过确认和超时机制在不可靠服务基础上实现可靠信息传输。若发送方在发送后一段时间内未收到确认帧，通常会重新发送。接收方无需请求发送方重传出错分组，重传请求自动进行 。</p><ol><li><strong>ARQ类型及特点</strong>：</li></ol><ul><li><strong>停止等待ARQ协议</strong>：</li><li>发送方每发送一个数据就停止发送，等待对方确认，收到确认后再发送下一个数据。需保留已发送数据副本，对数据和确认数据编号，超时计时器重传时间应比数据传输平均往返时间长 。</li><li>优点是简单，缺点是信道利用率低 。。</li><li><strong>连续ARQ协议</strong>：</li><li><strong>流水线传输</strong>：发送方可连续发送多个数据，信道上数据不间断传送，可获得高信道利用率 。</li><li><strong>累积确认</strong>：接收方对按序到达的最后一个数据发送确认，表示到该数据为止的所有数据都已正确收到。优点是容易实现，确认丢失也不必重传；缺点是不能向发送方反映已正确收到的所有数据信息 。</li><li><strong>Go - back - N（回退N）</strong>：若发送方发送多个数据，中间某个数据丢失，接收方只能对该数据之前的帧发出确认，发送方需重传该数据及其后续所有帧。当通信线路质量不好时，会带来负面影响 。</li><li><strong>TCP可靠通信实现</strong>：TCP连接两端设有发送窗口和接收窗口，用字节序号控制，确认基于序号而非报文段，窗口动态变化，需估算合理重传时间 。</li><li><strong>选择重传协议</strong>：仅重传丢失帧，需缓存乱序帧，实现复杂度高，适用于高丢包率/高带宽场景 。</li></ul><ol><li><strong>ARQ协议对比总结</strong>：</li></ol><table tabindex="0"><thead><tr><th>协议</th><th>停止等待ARQ</th><th>Go - Back - N</th><th>选择重传</th></tr></thead><tbody><tr><td>信道利用率</td><td>低（等待确认）</td><td>高（连续发送）</td><td>高（仅重传丢失帧）</td></tr><tr><td>重传策略</td><td>单帧超时重传</td><td>超时帧及其后续帧</td><td>仅超时帧</td></tr><tr><td>接收方缓存</td><td>无需缓存</td><td>无需缓存（丢弃乱序）</td><td>需要缓存乱序帧</td></tr><tr><td>实现复杂度</td><td>简单</td><td>中等</td><td>高（需缓存和序号管理）</td></tr><tr><td>应用场景</td><td>低带宽/高延迟链路</td><td>丢包率较低场景</td><td>高丢包率/高带宽场景</td></tr></tbody></table><h3 id="停止等待arq协议" tabindex="-1">停止等待ARQ协议 <a class="header-anchor" href="#停止等待arq协议" aria-label="Permalink to &quot;停止等待ARQ协议&quot;">​</a></h3><p>停止等待 ARQ 协议是一种简单的可靠传输协议，用于在不可靠的信道上实现可靠的数据传输，主要应用于数据链路层，也可用于传输层等场景 。以下是对该协议的详细介绍：</p><ol><li><strong>发送方操作</strong></li></ol><ul><li>发送方从应用层接收数据，将其封装成帧（数据链路层的协议数据单元），并为每个帧分配一个序号（通常从 0 开始，采用模 2 编号，即只有 0 和 1 两个序号 ） 。</li><li>发送方发送一个帧后，就进入等待状态，启动一个超时计时器。超时计时器的时长要合理设置，一般略大于从发送方到接收方的往返传播时延 。</li></ul><ol><li><strong>接收方操作</strong></li></ol><ul><li>接收方收到帧后，首先检查帧的正确性，例如通过校验和等方式检查帧在传输过程中是否出错 。</li><li>如果帧正确且序号正确（与期望接收的序号一致 ），接收方接收该帧，去除帧首部等信息后将数据交付给上层应用，并向发送方发送一个确认帧（ACK），确认帧中会包含对所接收帧的确认信息（通常携带接收帧的序号 ） 。</li><li>如果帧出错或者序号不正确（说明是重复帧 ），接收方丢弃该帧，不发送确认帧（或者发送否定确认帧 NAK ，不过实际中常采用不发送确认帧的方式 ） 。</li></ul><ol><li><strong>重传机制</strong></li></ol><ul><li>发送方若在超时计时器超时之前收到接收方的确认帧，说明帧已正确接收，发送方停止超时计时器，接着从应用层获取下一个数据帧进行发送 。</li><li>若超时计时器超时后仍未收到确认帧，发送方认为之前发送的帧丢失或接收方未正确接收，于是重传该帧，并重新启动超时计时器 。</li></ul><ol><li><strong>特点</strong></li></ol><ul><li>优点：简单 。</li><li>缺点：信道利用率太低 。</li></ul><ol><li><strong>示例</strong></li></ol><ul><li>无差错情况：A 发送 M1、M2、M3，B 分别确认 M1、M2、M3，各报文间有时间间隔 t 。</li><li>超时重传情况：A 发送 M1，B 未收到确认，超时后重传 M1，A 发送 M2，B 确认 M2，A 发送 M3，B 确认 M3 。</li></ul><h3 id="连续-arq-automatic-repeat-request-协议" tabindex="-1">连续 ARQ（Automatic Repeat reQuest）协议 <a class="header-anchor" href="#连续-arq-automatic-repeat-request-协议" aria-label="Permalink to &quot;连续 ARQ（Automatic Repeat reQuest）协议&quot;">​</a></h3><p>连续 ARQ（Automatic Repeat reQuest）协议是一种用于可靠数据传输的协议，它允许发送方在未收到确认的情况下连续发送多个数据帧，从而提高信道利用率。以下是关于连续 ARQ 协议的详细介绍：</p><ol><li><strong>协议概述</strong>连续 ARQ 协议是自动重传请求（ARQ）协议的一种，它结合了滑动窗口技术与请求重发技术。当窗口尺寸足够大时，数据在线路上可以连续流动，因此也被称为流水线协议。主要包括后退 N 帧协议（Go-Back-N，GBN）和选择重传协议（Selective Repeat，SR）两种类型 。</li><li><strong>工作原理</strong></li></ol><ul><li><strong>流水线传输</strong>：发送方可在发送窗口允许的范围内连续发送多个数据帧，无需等待每个帧的确认。例如，若发送窗口大小为 5，发送方可以依次发送序号为 0 - 4 的 5 个帧 。</li><li><strong>累积确认</strong>：接收方通常采用累积确认的方式，即对按序到达的最后一个数据帧发送确认，这意味着到该帧为止的所有数据帧都已正确接收。例如，若接收方收到了 0 - 3 号帧，则发送对 3 号帧的确认，表示 0 - 3 号帧均已正确接收 。</li><li><strong>超时重传</strong>：发送方为最早发送且未得到确认的帧启动超时计时器。若超时计时器超时，发送方将重传该帧及其后续所有已发送但未确认的帧（后退 N 帧协议），或者仅重传丢失的帧（选择重传协议） 。</li></ul><ol><li><strong>后退 N 帧协议（GBN）</strong></li></ol><ul><li><strong>特点</strong>：</li><li><strong>优点</strong>：信道利用率高，通过流水线传输和累积确认机制，减少了等待确认的时间，提高了数据传输效率 。</li><li><strong>缺点</strong>：当通信线路质量不好时，一旦某个帧丢失或出错，需要重传该帧及其后续的所有帧，可能导致大量的重复传输 。</li><li><strong>示例</strong>：发送方已经发送了编号为 0 - 7 的帧。当计时器超时时，若发送方只收到 0、2、3 号帧的确认，说明 1 号帧和 4 - 7 号帧可能丢失或出错，需要重传的帧数为 1、4、5、6、7（部分资料认为根据累积确认原理应重传 1 - 7 号帧） 。</li></ul><ol><li><strong>选择重传协议（SR）</strong></li></ol><ul><li><strong>特点</strong>：</li><li><strong>优点</strong>：仅重传丢失的帧，避免了后退 N 帧协议中不必要的重复传输，适用于高丢包率的场景 。</li><li><strong>缺点</strong>：接收方需要缓存乱序到达的帧，实现复杂度较高 。</li></ul><ol><li><strong>发送窗口和接收窗口</strong></li></ol><ul><li><strong>发送窗口</strong>：发送方维持一个发送窗口，规定了可以连续发送而不必等待确认的帧的序号范围。发送方每收到一个确认帧，就将发送窗口向前滑动相应的帧数 。</li><li><strong>接收窗口</strong>：接收方维持一个接收窗口，规定了可以接收的帧的序号范围。接收方每接收一个正确的帧，就将接收窗口向前滑动相应位置，准备接收后续帧 。</li></ul><h4 id="后退n帧协议" tabindex="-1">后退N帧协议 <a class="header-anchor" href="#后退n帧协议" aria-label="Permalink to &quot;后退N帧协议&quot;">​</a></h4><p>**后退N帧协议（GBN）**是数据链路层采用的一种协议，其主要特点和工作原理如下：</p><ol><li><strong>协议概述</strong>：后退N帧协议是连续ARQ协议的一种，它允许发送方在未收到确认的情况下连续发送多个数据帧，从而提高信道利用率。当发送方收到接收方的确认帧时，会滑动发送窗口；如果某个帧超时未收到确认，发送方将重传该帧及其后续的所有帧 。</li><li><strong>协议原理</strong></li></ol><ul><li><strong>流水线传输</strong>：发送方可连续发送多个数据帧，不必每发完一个数据帧就停顿下来等待对方的确认。由于信道上一直有数据不间断地传送，这种传输方式可获得很高的信道利用率 。</li><li><strong>累积确认</strong>：接收方一般采用累积确认的方式，即不必对收到的数据帧逐个发送确认，而是对按序到达的最后一个数据帧发送确认，这样就表示到这个数据帧为止的所有数据帧都已正确收到了 。</li><li><strong>超时重传</strong>：如果发送方发送了多个数据帧，而中间的某个数据帧丢失了，这时接收方只能对该数据帧之前的帧发出确认，发送方无法知道后面数据帧的下落，而只好把该数据帧及其后面的所有数据帧都再重传一次，这就叫后退N帧（Go-back-N） 。</li></ul><ol><li><strong>协议示例</strong>：在后退N帧协议中，发送方已经发送了编号为0 - 7的帧。当计时器超时时，若发送方只收到0、2、3号帧的确认，说明1号帧和4 - 7号帧可能丢失或出错，所以需要重传的帧数为1、4、5、6、7，共5帧（注意：这里的答案可能存在争议，根据累积确认的原理，应该重传1 - 7号帧，但部分资料认为只重传1、4、5、6、7号帧，共4帧） 。</li><li><strong>协议特点</strong></li></ol><ul><li><strong>优点</strong>：信道利用率高，通过流水线传输和累积确认机制，减少了等待确认的时间，提高了数据传输效率 。</li><li><strong>缺点</strong>：当通信线路质量不好时，后退N帧协议会带来负面的影响，因为一旦某个帧丢失或出错，需要重传该帧及其后续的所有帧，可能导致大量的重复传输 。</li></ul><h4 id="选择重传协议" tabindex="-1">选择重传协议 <a class="header-anchor" href="#选择重传协议" aria-label="Permalink to &quot;选择重传协议&quot;">​</a></h4><p>选择重传协议（SR）是数据链路层采用的协议，其主要特点和工作原理如下：</p><ol><li><strong>协议概述</strong>：选择重传协议允许发送方在未收到确认的情况下连续发送多个数据帧，从而提高信道利用率。当某个帧超时未收到确认时，仅重传该超时帧，而不是像后退N帧协议那样重传该帧及其后续的所有帧。</li><li><strong>协议原理</strong>：</li></ol><ul><li><strong>流水线传输</strong>：发送方可连续发送多个数据帧，不必每发完一个数据帧就停顿下来等待对方的确认，提高了信道利用率。</li><li><strong>非累积确认</strong>：接收方对每个正确接收的帧都单独发送确认，而不是采用累积确认的方式。</li><li><strong>超时重传</strong>：发送方为每个已发送但未确认的帧设置计时器，当某帧超时，仅重传该超时帧。</li></ul><ol><li><strong>协议示例</strong>：在选择重传协议中，发送方已经发送了0 - 3号数据帧，现已收到1号帧的确认，而0、2号帧依次超时，则此时需要重传0号和2号帧，共2帧。</li><li><strong>协议特点</strong>：</li></ol><ul><li><strong>优点</strong>：仅重传丢失的帧，避免了后退N帧协议中可能出现的大量重复传输，提高了传输效率。</li><li><strong>缺点</strong>：需要接收方有较大的缓存空间来缓存乱序到达的帧，实现复杂度较高。</li></ul><ol><li><strong>应用场景</strong>：适用于高丢包率、高带宽的场景，如无线通信等。</li></ol><h2 id="历年真题-4" tabindex="-1">历年真题 <a class="header-anchor" href="#历年真题-4" aria-label="Permalink to &quot;历年真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【国家电网（2014年）】以下为广域网协议的有 ( )A. PPP B. X.25 C. SLIP D. FrameRelay答案 ：ABCD解析 ：PPP（点到点协议）、X.25（公用数据网协议）、SLIP（串行线路网际协议）、FrameRelay（帧中继）均属于广域网协议</th></tr></thead></table><table tabindex="0"><thead><tr><th>【中国铁塔（2018）】下列协议中，不属于数据链路层协议的是（ ）A. PPPB. HDLCC. ARPD. TCP答案：D解析：PPP（点到点协议）、HDLC（高级数据链路控制）都是典型的数据链路层协议，用于实现链路建立、数据传输和链路释放等功能。ARP（地址解析协议）虽常被认为与链路层紧密相关，但也属于网络层协议，用于将 IP 地址解析为 MAC 地址。而 TCP（传输控制协议）是传输层协议，提供可靠的面向连接的传输服务。</th></tr></thead></table><table tabindex="0"><thead><tr><th>【南方电网（2023）】数据链路层采用了后退 N 帧（GBN）协议，发送方已经发送了编号为 0 - 7 的帧。当计时器超时时，若发送方只收到 0、2、3 号帧的确认，则发送方需要重发的帧数是（ ）A. 2B. 3C. 4D. 5答案：C解析：在后退 N 帧协议中，发送方收到的确认号表示该序号及之前的帧已正确接收。本题中发送方只收到 0、2、3 号帧的确认，说明 1 号帧和 4 - 7 号帧可能丢失或出错，所以需要重发的帧数为 1、4、5、6、7，共 4 帧。</th></tr></thead></table><table tabindex="0"><thead><tr><th>【南方电网（2020）】以下关于 PPP 协议的描述，错误的是（ ）A. 支持多种网络层协议B. 提供错误检测功能C. 采用可靠传输机制D. 支持认证功能答案：C解析：PPP 协议支持多种网络层协议，如 IP、IPX 等；具有错误检测功能，可检测数据传输过程中的错误；支持 PAP（密码验证协议）和 CHAP（挑战握手验证协议）等认证功能。但 PPP 协议通常不采用可靠传输机制，它只进行差错检测，不保证数据一定能正确传输到对端，对于可靠性由上层协议来保证。</th></tr></thead></table><h2 id="局域网" tabindex="-1">局域网 <a class="header-anchor" href="#局域网" aria-label="Permalink to &quot;局域网&quot;">​</a></h2><h2 id="什么是局域网" tabindex="-1">什么是局域网？ <a class="header-anchor" href="#什么是局域网" aria-label="Permalink to &quot;什么是局域网？&quot;">​</a></h2><h3 id="局域网概念" tabindex="-1">局域网概念 <a class="header-anchor" href="#局域网概念" aria-label="Permalink to &quot;局域网概念&quot;">​</a></h3><p>局域网（Local Area Network，LAN）是指在某一区域内由多台计算机互联成的计算机组。一般是方圆几千米以内。局域网可以实现文件管理、应用软件共享、打印机共享、工作组内的日程安排、电子邮件和传真通信服务等功能。</p><h3 id="局域网主要特点" tabindex="-1">局域网主要特点 <a class="header-anchor" href="#局域网主要特点" aria-label="Permalink to &quot;局域网主要特点&quot;">​</a></h3><ol><li>覆盖范围小：通常局限于一个建筑物内、一个校园或一个企业园区等较小的地理区域，一般在几千米以内。</li><li>数据传输速率高：一般可达到 10Mbps - 1000Mbps 甚至更高，能满足大量数据的快速传输需求。</li><li>误码率低：由于传输距离短，信号传输质量好，受外界干扰小，所以误码率通常较低，一般在 10⁻⁸到 10⁻¹¹ 之间。</li><li>拓扑结构简单：常见的拓扑结构有总线型、星型、环型、树型和网状型等，易于实现和管理。</li><li>通信协议简单：通常采用以太网协议等简单高效的通信协议，以实现快速的数据传输和共享。</li></ol><h3 id="局域网主要优点" tabindex="-1">局域网主要优点 <a class="header-anchor" href="#局域网主要优点" aria-label="Permalink to &quot;局域网主要优点&quot;">​</a></h3><ol><li>资源共享方便：可以方便地实现硬件资源（如打印机、扫描仪等）和软件资源（如应用程序、文件等）的共享，提高资源利用率，降低成本。</li><li>数据传输速度快：能够快速地传输数据，满足用户对实时性要求较高的应用，如视频会议、在线游戏等。</li><li>易于管理和维护：由于覆盖范围小，设备数量相对较少，网络结构简单，因此管理和维护工作相对容易，成本也较低。</li><li>安全性较高：可以通过设置访问权限、防火墙等措施，对局域网内的资源进行保护，相对广域网来说，安全性更容易得到保障。</li></ol><h2 id="以太网" tabindex="-1">以太网 <a class="header-anchor" href="#以太网" aria-label="Permalink to &quot;以太网&quot;">​</a></h2><p>以太网（Ethernet）是一种广泛应用的局域网技术，以太网最初由Xerox、DEC和Intel三家公司在20世纪70年代末期共同推出。世界上第一个局域网产品（以太网）的规约是DIX Ethernet V2，而IEEE的802.3标准与DIX Ethernet V2标准只有很小的差别，因此常将802.3局域网简称为“以太网”，严格来说，“以太网”应当是指符合DIX Ethernet V2标准的局域网。</p><h3 id="以太网工作原理" tabindex="-1">以太网工作原理 <a class="header-anchor" href="#以太网工作原理" aria-label="Permalink to &quot;以太网工作原理&quot;">​</a></h3><p>以太网采用带冲突检测的载波监听多路访问（CSMA/CD）机制来控制网络中数据的传输。网络中的每个节点在发送数据前，都会先监听网络是否空闲。如果网络空闲，节点就可以发送数据；在发送数据的同时，节点会继续监听网络，以检测是否发生冲突。如果检测到冲突，节点会立即停止发送数据，并发送一个阻塞信号，通知其他节点发生了冲突。然后，节点会等待一段随机时间后再次尝试发送数据，直到数据成功发送为止。</p><h3 id="csma-cd协议" tabindex="-1">CSMA/CD协议 <a class="header-anchor" href="#csma-cd协议" aria-label="Permalink to &quot;CSMA/CD协议&quot;">​</a></h3><p><img src="'+q+'" alt=""></p><p>CSMA协议是对总线型拖补结构的以太网进行访问控制的协议，尽最大努力的交付，即不可靠的交付，CSMA协议的特点是：<strong>先听先发，边发边听，碰撞停发，随机延迟后重发。</strong></p><ol><li>载波监听：每个节点在发送数据之前，都要持续监听信道。通过监听，节点可以判断信道上是否有其他节点正在发送数据。若信道忙（有载波信号），则等待；若信道空闲，则可以发送数据。</li><li>冲突检测：在发送数据的过程中，节点同时检测信道上的信号。如果检测到的信号电压变化幅度超过了正常发送信号的幅度，就说明发生了冲突。这是因为当两个或多个节点同时发送数据时，信号会在信道上叠加，导致信号幅度异常。</li><li>冲突处理：一旦检测到冲突，发送节点会立即停止发送数据，并发送一个简短的阻塞信号，以确保网络中的其他节点都能知道发生了冲突。然后，每个参与冲突的节点会进入退避阶段，等待一段随机时间后再次尝试发送数据。退避时间通常根据截断二进制指数退避算法来确定，该算法可以使冲突的节点以不同的概率选择退避时间，从而减少再次冲突的可能性。</li></ol><h3 id="以太网的mac帧" tabindex="-1">以太网的MAC帧 <a class="header-anchor" href="#以太网的mac帧" aria-label="Permalink to &quot;以太网的MAC帧&quot;">​</a></h3><p><img src="'+m+'" alt=""></p><ol><li>目的地址：占 6 个字节，用于标识接收帧的目的节点的 MAC 地址。</li><li>源地址：占 6 个字节，标识发送帧的源节点的 MAC 地址。</li><li>类型：占 2 个字节，用于指示上层使用的协议类型，如 IP 协议、ARP 协议等。</li><li>数据：长度在 46 - 1500 字节之间，包含了要发送的上层协议数据。如果上层协议数据长度小于 46 字节，需要进行填充，以保证 MAC 帧的数据部分长度不小于 46 字节。</li><li>帧校验序列（FCS）：占 4 个字节，采用循环冗余校验（CRC）算法对 MAC 帧除 FCS 字段以外的所有字段进行校验，用于检测帧在传输过程中是否发生错误。</li></ol><h3 id="以太网的传输介质" tabindex="-1">以太网的传输介质 <a class="header-anchor" href="#以太网的传输介质" aria-label="Permalink to &quot;以太网的传输介质&quot;">​</a></h3><table tabindex="0"><thead><tr><th>传输介质</th><th>特点</th><th>传输距离</th><th>应用场景</th></tr></thead><tbody><tr><td>粗缆</td><td>直径较大，抗干扰能力强，传输性能较好，但成本高、安装难度大</td><td>可达 500 米</td><td>早期大型局域网，如校园网、大型企业园区网络骨干部分</td></tr><tr><td>细缆</td><td>直径较小，相对灵活，成本较低，但抗干扰能力稍弱，传输距离较短</td><td>一般为 185 米左右</td><td>小型局域网，如小型办公室、家庭局域网的早期应用</td></tr><tr><td>双绞线</td><td>成本低、易于安装和维护，分为屏蔽和非屏蔽类型，非屏蔽双绞线易受干扰，屏蔽双绞线抗干扰能力较好</td><td>一般不超过 100 米</td><td>广泛应用于各种办公、家庭网络等局域网环境</td></tr><tr><td>光纤</td><td>带宽高、传输距离远、抗干扰能力极强，但成本高、安装和维护要求专业技术</td><td>多模光纤可达 2 公里左右，单模光纤可达数十公里甚至更远</td><td>骨干网络、长距离传输网络、对电磁环境要求高的场所，如数据中心、金融机构等</td></tr></tbody></table><h3 id="高速以太网" tabindex="-1">高速以太网 <a class="header-anchor" href="#高速以太网" aria-label="Permalink to &quot;高速以太网&quot;">​</a></h3><ol><li><strong>快速以太网（Fast Ethernet）</strong></li></ol><p>数据传输速率为 100Mbps，保留了传统以太网的帧格式、介质访问控制方法（CSMA/CD）以及网络拓扑结构等，只是将数据传输速率提高了 10 倍。它可以使用双绞线或光纤作为传输介质，其中 100Base - TX 使用两对 5 类或更高等级的 UTP 双绞线，100Base - FX 使用光纤。</p><ol><li><strong>吉比特以太网（Gigabit Ethernet）</strong></li></ol><p>传输速率为 1Gbps。同样保留了以太网的基本特征，在物理层进行了改进，以支持更高的传输速率。它可以使用多种传输介质，如 1000Base - T 使用 4 对 5 类或超 5 类 UTP 双绞线，1000Base - SX 和 1000Base - LX 分别使用多模光纤和单模光纤。</p><ol><li><strong>10 吉比特以太网（10 - Gigabit Ethernet）</strong></li></ol><p>数据传输速率高达 10Gbps。主要应用于骨干网络、数据中心等对带宽要求极高的场景。它通常使用光纤作为传输介质，并且只支持全双工模式，不再使用 CSMA/CD 协议，因为在高速率下，冲突检测的开销过大。</p><h2 id="虚拟局域网" tabindex="-1">虚拟局域网 <a class="header-anchor" href="#虚拟局域网" aria-label="Permalink to &quot;虚拟局域网&quot;">​</a></h2><p>**虚拟局域网（Virtual Local Area Network，VLAN）是一种将局域网内的设备逻辑地而不是物理地划分成不同网段的技术。**VLAN 通过在交换机上进行配置，将不同端口连接的设备划分到不同的逻辑网络中，这些逻辑网络就像是独立的物理局域网一样，不同 VLAN 之间的设备默认情况下无法直接通信，从而实现了网络的隔离和管理。</p><p>当交换机收到一个数据包时，它会根据数据包的源 MAC 地址和端口信息，在 VLAN 映射表中查找该端口所属的 VLAN。然后，交换机根据目的 MAC 地址或目的 IP 地址等信息，判断该数据包是否需要在本 VLAN 内转发，还是需要通过三层设备（如路由器）转发到其他 VLAN。如果是在本 VLAN 内转发，交换机就会根据 MAC 地址表将数据包转发到对应的端口；如果需要转发到其他 VLAN，交换机就会将数据包发送给三层设备，由三层设备进行路由转发。</p><h2 id="历年真题-5" tabindex="-1">历年真题 <a class="header-anchor" href="#历年真题-5" aria-label="Permalink to &quot;历年真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>以太网 MAC 子层的协议数据单元是（ ）A. IP 数据报B. 帧C. 比特流D. 分组答案：B解析：以太网 MAC（介质访问控制）子层属于数据链路层，其协议数据单元是帧。MAC 子层负责将上层传来的数据封装成帧，并通过物理层发送到网络中，同时处理帧的接收和错误检测等功能 。</th></tr></thead></table><h2 id="广域网" tabindex="-1">广域网 <a class="header-anchor" href="#广域网" aria-label="Permalink to &quot;广域网&quot;">​</a></h2><h2 id="广域网概念" tabindex="-1">广域网概念 <a class="header-anchor" href="#广域网概念" aria-label="Permalink to &quot;广域网概念&quot;">​</a></h2><p>广域网（Wide Area Network，WAN）是一种覆盖范围广泛的计算机网络，它可以跨越城市、国家甚至全球范围，将不同地理位置的局域网或计算机连接起来，实现远距离的数据通信和资源共享。广域网通常使用公共通信网络，如电话网络、卫星通信网络、微波通信网络等作为传输载体，通过路由器、交换机等网络设备进行数据的传输和交换。</p><h2 id="广域网与局域网关系" tabindex="-1">广域网与局域网关系 <a class="header-anchor" href="#广域网与局域网关系" aria-label="Permalink to &quot;广域网与局域网关系&quot;">​</a></h2><ol><li>相互连接：广域网可以将多个局域网连接在一起，使不同局域网中的设备能够进行通信和资源共享。例如，一家企业在不同城市设有分支机构，每个分支机构都有自己的局域网，通过广域网将这些局域网连接起来，就可以实现企业内部的信息交流和业务协同。</li><li>互补作用：局域网侧重于满足局部区域内设备的高速互联和资源共享需求，而广域网则解决了远距离设备之间的通信问题。两者相互补充，共同构成了复杂的计算机网络体系，以满足用户在不同范围内的通信和数据处理需求。</li></ol><h2 id="广域网与局域网区别" tabindex="-1">广域网与局域网区别 <a class="header-anchor" href="#广域网与局域网区别" aria-label="Permalink to &quot;广域网与局域网区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>比较项目</th><th>广域网</th><th>局域网</th></tr></thead><tbody><tr><td>覆盖范围</td><td>通常覆盖城市、国家甚至全球，跨度可达数千千米以上</td><td>一般局限于一个建筑物、校园或企业园区内，范围在几千米以内</td></tr><tr><td>传输介质</td><td>借助公共通信网络的传输介质，如电话线、卫星链路、微波等</td><td>多使用双绞线、光纤等，部分也会用同轴电缆</td></tr><tr><td>数据传输速率</td><td>相对较低，常见几十 Kbps 到几 Mbps，虽有高速技术但总体低于局域网</td><td>较高，一般为 100Mbps、1000Mbps 甚至更高</td></tr><tr><td>网络拓扑结构</td><td>较为复杂，常采用网状型、树型等结构，以实现大规模网络连接和数据传输</td><td>相对简单，常见星型、总线型、环型等结构，易于管理和维护</td></tr><tr><td>建设和管理</td><td>建设和管理涉及多个网络服务提供商和不同管理机构，成本高、难度大</td><td>通常由一个单位或组织负责建设和管理，成本相对较低，管理相对集中和简单</td></tr><tr><td>通信协议</td><td>使用多种复杂的通信协议，以适应不同的网络环境和传输需求，如 PPP、HDLC、帧中继等</td><td>常使用较为简单和标准化的协议，如以太网协议（IEEE 802.3）等</td></tr><tr><td>传输延迟</td><td>由于传输距离远，信号传播、路由选择等过程复杂，传输延迟较大</td><td>传输距离短，信号传播和处理速度快，传输延迟较小</td></tr><tr><td>可靠性</td><td>受多种因素影响，如网络拥塞、线路故障等，可靠性相对较低，但通过冗余设计等手段可提高</td><td>内部环境相对稳定，设备和线路可靠性较高，且可通过备份等措施保证高可靠性</td></tr><tr><td>安全性</td><td>面临更复杂的安全威胁，需要采取多种安全措施，如防火墙、VPN 等</td><td>相对安全，但也需采取访问控制、加密等措施保障安全</td></tr></tbody></table><h2 id="历年真题-6" tabindex="-1">历年真题 <a class="header-anchor" href="#历年真题-6" aria-label="Permalink to &quot;历年真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【国家电网 （2016 ）】广域网的通信子网主要使用（ ）技术A. 电路交换B. 分组交换C. 报文交换D. 电话交换答案 ：B解析 ：广域网的通信子网主要使用分组交换技术，将分布在不同地区的局域网或计算机系统互联起来，达到资源共享的目的。</th></tr></thead></table><table tabindex="0"><thead><tr><th>【南方电网 （2017 ）】广域网一般采用网状拓扑构型，该构型的系统可靠性高，但是结构复杂。为了实现正确的传输必须采用（ ）A. 光纤传输技术、路由选择算法B. 光纤传输技术、无线通信技术C. 路由选择算法、流量控制方法D. 无线通信技术、流量控制方法答案 ：C解析 ：网状拓扑结点之间的连接是任意的，可靠性高，结构复杂，广域网基本上都采用这种构型。网状拓扑的优点是系统可靠性高，但是结构复杂，必须采用路由选择算法与流量控制方法来实现正确的传输。</th></tr></thead></table>',256)])])}const N=a(f,[["render",x]]);export{B as __pageData,N as default};
